html:
{%- import "altor_project/templates/print/altor_print.html" as ap with context -%}
{%- set c = altor_company(doc.company, doc) -%}
{{ ap.styles(c) }}
{%- set p = altor_party(doc) -%}
{%- set vat = altor_item_taxes(doc) -%}
<div class="ap">
{{ ap.header(c, "PROFORMA INVOICE", "فاتورة مبدئية", [
    ["Proforma No.", doc.name],
    ["Date", ap.date(doc.transaction_date)],
    ["Valid Till", ap.date(doc.valid_till)],
    ["Quotation", doc.get("quotation")],
    ["Sales Order", doc.get("sales_order")]
]) }}
{{ ap.two_boxes(ap.party_box("Bill To", p), ap.info_box("Details", [
    ["Order Type", doc.get("order_type")],
    ["Currency", doc.currency],
    ["Payment Terms", doc.get("payment_terms_template")],
    ["Sales Person", doc.get("sales_person")]
])) }}
<table class="items">
  <thead><tr>
    <th style="width:5%">#<span class="ar">رقم</span></th>
    <th>Description<span class="ar">البيان</span></th>
    <th style="width:7%">Unit<span class="ar">الوحدة</span></th>
    <th class="right" style="width:7%">Qty<span class="ar">الكمية</span></th>
    <th class="right" style="width:11%">Rate<span class="ar">سعر الوحدة</span></th>
    <th class="right" style="width:12%">Taxable<span class="ar">المبلغ الخاضع</span></th>
    <th class="right" style="width:7%">VAT %<span class="ar">النسبة</span></th>
    <th class="right" style="width:10%">VAT<span class="ar">الضريبة</span></th>
    <th class="right" style="width:12%">Total ({{ doc.currency }})<span class="ar">الإجمالي</span></th>
  </tr></thead>
  <tbody>
  {%- for item in doc.get("items") %}{% set t = vat[item.name] %}
  <tr><td>{{ loop.index }}</td><td><div class="item-name">{{ item.item_name }}</div>{% if item.description and item.description | striptags | trim != item.item_name %}{{ ap.bullets(item.description) }}{% endif %}</td>
    <td>{{ item.uom }}</td><td class="right">{{ ap.num(item.qty) }}</td><td class="right">{{ ap.amt(item.rate) }}</td>
    <td class="right">{{ ap.amt(t.net) }}</td><td class="right">{{ t.rate }}%</td><td class="right">{{ ap.amt(t.amount) }}</td><td class="right"><b>{{ ap.amt(t.total) }}</b></td></tr>
  {%- endfor %}
  </tbody>
</table>
{{ ap.totals(doc) }}
{{ ap.section("Payment Terms", ap.payment_terms(doc)) }}
{{ ap.section("Terms & Conditions", doc.get("terms")) }}
{{ ap.bank(c) }}
<p class="muted" style="margin-top:8px">This is a proforma invoice and not a tax invoice. A tax invoice will be issued on supply / receipt of payment.</p>
{{ ap.signatures(c, ["Authorised Signatory", "Received by"]) }}
{{ ap.footer(c) }}
</div>
